-- Initial schema, PLAN section 6.
-- Ids are UUIDv7 generated by the app (time ordered); the DB default is only a fallback.
-- Every table that holds tenant data carries tenant_id, and every query filters on it (PLAN D1).

-- +goose Up

-- +goose StatementBegin
CREATE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
-- +goose StatementEnd

CREATE TABLE tenants (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    slug                text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9][a-z0-9-]{1,62}$'),
    name                text NOT NULL,
    api_key             text NOT NULL UNIQUE,
    -- AES-256-GCM with MARPOKAT_MASTER_KEY (nonce || ciphertext)
    api_secret_enc      bytea NOT NULL,
    config              jsonb NOT NULL DEFAULT '{}'::jsonb,
    fcm_credentials_enc bytea,
    webhook_url         text,
    webhook_secret_enc  bytea,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    disabled_at         timestamptz
);
CREATE TRIGGER tenants_updated_at BEFORE UPDATE ON tenants FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE users (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id   uuid NOT NULL REFERENCES tenants (id),
    external_id text NOT NULL CHECK (length(external_id) BETWEEN 1 AND 255),
    name        text NOT NULL DEFAULT '',
    avatar_url  text,
    metadata    jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    deleted_at  timestamptz,
    UNIQUE (tenant_id, external_id)
);
CREATE TRIGGER users_updated_at BEFORE UPDATE ON users FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE channels (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id        uuid NOT NULL REFERENCES tenants (id),
    type             text NOT NULL CHECK (type IN ('dm', 'group')),
    name             text,
    avatar_url       text,
    -- "{tenant_id}:{smaller user id}:{larger user id}": one DM per pair of users (PLAN section 6)
    dm_key           text UNIQUE,
    -- one counter per channel: every message, edit, delete and reaction takes the next value (PLAN D8)
    last_seq         bigint NOT NULL DEFAULT 0,
    -- seq of the latest message only (unread count)
    last_message_seq bigint NOT NULL DEFAULT 0,
    last_message_at  timestamptz,
    created_by       uuid REFERENCES users (id),
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    frozen_at        timestamptz,
    deleted_at       timestamptz,
    CHECK ((type = 'dm') = (dm_key IS NOT NULL))
);
CREATE INDEX channels_tenant_updated_idx ON channels (tenant_id, updated_at);
CREATE TRIGGER channels_updated_at BEFORE UPDATE ON channels FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE channel_members (
    channel_id    uuid NOT NULL REFERENCES channels (id) ON DELETE CASCADE,
    user_id       uuid NOT NULL REFERENCES users (id),
    tenant_id     uuid NOT NULL REFERENCES tenants (id),
    role          text NOT NULL DEFAULT 'member' CHECK (role IN ('owner', 'admin', 'member')),
    last_read_seq bigint NOT NULL DEFAULT 0,
    muted_until   timestamptz,
    joined_at     timestamptz NOT NULL DEFAULT now(),
    left_at       timestamptz,
    PRIMARY KEY (channel_id, user_id)
);
-- "channels of user X": the channel list and the realtime routing both start here
CREATE INDEX channel_members_active_user_idx ON channel_members (user_id) WHERE left_at IS NULL;

CREATE TABLE messages (
    channel_id      uuid NOT NULL REFERENCES channels (id) ON DELETE CASCADE,
    seq             bigint NOT NULL,
    id              uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    tenant_id       uuid NOT NULL REFERENCES tenants (id),
    -- NULL for system messages
    sender_id       uuid REFERENCES users (id),
    -- idempotency key chosen by the client (PLAN D9)
    client_msg_id   text CHECK (length(client_msg_id) <= 64),
    type            text NOT NULL CHECK (type IN ('text', 'media', 'system')),
    text            text CHECK (length(text) <= 10000),
    attachments     jsonb NOT NULL DEFAULT '[]'::jsonb,
    reply_to_id     uuid,
    reaction_counts jsonb NOT NULL DEFAULT '{}'::jsonb,
    metadata        jsonb NOT NULL DEFAULT '{}'::jsonb,
    -- seq of the latest change to this row; sync reads rev_seq > cursor (PLAN D8)
    rev_seq         bigint NOT NULL,
    edited_at       timestamptz,
    deleted_at      timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (channel_id, seq),
    UNIQUE (channel_id, sender_id, client_msg_id),
    CHECK (rev_seq >= seq)
);
CREATE INDEX messages_channel_rev_idx ON messages (channel_id, rev_seq);

CREATE TABLE message_reactions (
    message_id uuid NOT NULL REFERENCES messages (id) ON DELETE CASCADE,
    user_id    uuid NOT NULL REFERENCES users (id),
    emoji      text NOT NULL CHECK (length(emoji) BETWEEN 1 AND 64),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (message_id, user_id, emoji)
);

CREATE TABLE attachments (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id   uuid NOT NULL REFERENCES tenants (id),
    uploader_id uuid NOT NULL REFERENCES users (id),
    object_key  text NOT NULL UNIQUE,
    mime        text NOT NULL,
    size        bigint NOT NULL CHECK (size > 0),
    file_name   text CHECK (length(file_name) <= 255),
    width       integer,
    height      integer,
    duration_ms integer,
    thumb_key   text,
    blurhash    text,
    status      text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'processing', 'ready', 'failed')),
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now()
);
-- cleanup job: pending uploads that were never completed
CREATE INDEX attachments_pending_idx ON attachments (created_at) WHERE status = 'pending';
CREATE TRIGGER attachments_updated_at BEFORE UPDATE ON attachments FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE devices (
    tenant_id  uuid NOT NULL REFERENCES tenants (id),
    push_token text NOT NULL,
    user_id    uuid NOT NULL REFERENCES users (id),
    platform   text NOT NULL CHECK (platform IN ('android', 'web')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    -- a device token belongs to whoever registered it last (shared device, account switch)
    PRIMARY KEY (tenant_id, push_token)
);
CREATE INDEX devices_user_idx ON devices (user_id);
CREATE TRIGGER devices_updated_at BEFORE UPDATE ON devices FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Transactional outbox (PLAN D6): written in the same transaction as the change, published by the worker relay.
CREATE TABLE outbox (
    id           bigserial PRIMARY KEY,
    event_id     uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    tenant_id    uuid NOT NULL REFERENCES tenants (id),
    topic        text NOT NULL,
    payload      jsonb NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    attempts     integer NOT NULL DEFAULT 0,
    last_error   text
);
-- the relay only ever scans unpublished rows, in id order
CREATE INDEX outbox_unpublished_idx ON outbox (id) WHERE published_at IS NULL;
-- cleanup job: published rows older than 7 days
CREATE INDEX outbox_published_idx ON outbox (published_at) WHERE published_at IS NOT NULL;

-- +goose Down
DROP TABLE outbox;
DROP TABLE devices;
DROP TABLE attachments;
DROP TABLE message_reactions;
DROP TABLE messages;
DROP TABLE channel_members;
DROP TABLE channels;
DROP TABLE users;
DROP TABLE tenants;
DROP FUNCTION set_updated_at();
